import React from "react";
import { Link } from "gatsby";

export type PropertiesMiniHeroProps = {
  image: { src: string; srcSet?: string; alt: string };
  eyebrow: string;
  title: string;
  lede: string;
  /** Fitted background word, as established in MTC-KRP-002. */
  backgroundText?: string;
  children?: React.ReactNode;
};

/**
 * The banner at the top of the search page.
 *
 * Shorter than the homepage hero on purpose — this page is a tool, and the
 * search panel below it is the thing the visitor came for. The ghost word is
 * used once, here, and nowhere near the filter controls: outlined display type
 * behind a checkbox list would be decoration fighting usability.
 */
export default function PropertiesMiniHero({
  image,
  eyebrow,
  title,
  lede,
  backgroundText,
  children,
}: PropertiesMiniHeroProps) {
  return (
    <section className="kr-phero">
      <div className="kr-phero__media">
        <img
          className="kr-phero__image"
          src={image.src}
          srcSet={image.srcSet}
          sizes={image.srcSet ? "100vw" : undefined}
          alt={image.alt}
          loading="eager"
          decoding="sync"
        />
        <span className="kr-phero__scrim" aria-hidden="true" />
      </div>

      {backgroundText ? (
        <span
          className="kr-phero__ghost"
          aria-hidden="true"
          style={
            { ["--kr-ghost-chars" as string]: String(backgroundText.length) } as React.CSSProperties
          }
        >
          {backgroundText}
        </span>
      ) : null}

      <div className="kr-phero__inner">
        <div className="kr-phero__content">
          <span className="kr-phero__rule" aria-hidden="true" />
          <p className="kr-phero__eyebrow">{eyebrow}</p>
          <h1 className="kr-phero__title">{title}</h1>
          <p className="kr-phero__lede">{lede}</p>

          <nav className="kr-phero__crumbs" aria-label="Breadcrumb">
            <ol>
              <li>
                <Link to="/">Home</Link>
              </li>
              <li>
                <span aria-current="page">Properties</span>
              </li>
            </ol>
          </nav>
        </div>
      </div>

      {children}
    </section>
  );
}
