import React from "react";
import type { HeadFC, PageProps } from "gatsby";

import Layout from "../components/Layout";
import PropertiesSearchX from "../ppm/primitives/properties-search/properties-search-x";

/**
 * The properties search page.
 *
 * Running order only. Everything the page shows — the banner, the search
 * panel, the filters, the results — is assembled in the primitive, which is
 * the same division of labour the homepage and property pages use.
 */
export default function PropertiesPage(_props: PageProps) {
  return (
    <Layout>
      <PropertiesSearchX />
    </Layout>
  );
}

export const Head: HeadFC = () => (
  <>
    <title>Properties | Kelley Road Property Management</title>
    <meta
      name="description"
      content="Search Kelley Road managed homes by location, property type, bedrooms, rent and amenities. Apartments, townhomes, studios and houses across Massachusetts."
    />
  </>
);
