import React, { useId, useState } from "react";
import { LuMinus, LuPlus } from "react-icons/lu";

export type FilterGroupProps = {
  title: string;
  /** Open on first render. The groups people use most start open. */
  defaultOpen?: boolean;
  /** Shown beside the title when the group has selections. */
  activeCount?: number;
  children: React.ReactNode;
};

/**
 * One collapsible block in the filter panel.
 *
 * A real button controlling a real region, so it works from the keyboard and
 * announces its state, rather than a div with a click handler. The divider is
 * the group's own bottom border, which is why there is no separate rule
 * element between groups.
 */
export default function FilterGroup({
  title,
  defaultOpen = false,
  activeCount = 0,
  children,
}: FilterGroupProps) {
  const [open, setOpen] = useState(defaultOpen);
  const panelId = useId();

  return (
    <div
      className={`kr-fgroup${open ? " kr-fgroup--open" : ""}${
        activeCount ? " kr-fgroup--active" : ""
      }`}
    >
      <h3 className="kr-fgroup__heading">
        <button
          type="button"
          className="kr-fgroup__toggle"
          aria-expanded={open}
          aria-controls={panelId}
          onClick={() => setOpen((current) => !current)}
        >
          <span className="kr-fgroup__title">
            {title}
            {activeCount ? (
              <span className="kr-fgroup__count">{activeCount}</span>
            ) : null}
          </span>
          <span className="kr-fgroup__icon" aria-hidden="true">
            {open ? <LuMinus size={15} strokeWidth={2} /> : <LuPlus size={15} strokeWidth={2} />}
          </span>
        </button>
      </h3>

      <div className="kr-fgroup__panel" id={panelId} hidden={!open}>
        <div className="kr-fgroup__body">{children}</div>
      </div>
    </div>
  );
}
