// Styling for the SelectMenu listbox.
//
// Separate from the pages that use it because the whole point of replacing the
// native select was to bring the open state inside the design system; a menu
// styled once, here, is a menu that cannot drift between the search bar, the
// sort control and whatever uses it next.

import brand from "../brand";

export type SelectTemplate = {
  css: string;
};

const color = {
  buttonText: brand.colors.text,
  buttonPlaceholder: brand.colors.textMuted,
  buttonIcon: brand.colors.accent,
  buttonCaret: brand.colors.textMuted,

  menuBackground: brand.colors.background,
  menuBorder: brand.colors.border,
  menuShadow: "0 12px 32px rgba(31, 35, 40, .14), 0 2px 6px rgba(31, 35, 40, .06)",

  optionText: brand.colors.text,
  optionPlaceholder: brand.colors.textMuted,
  /* Hover and keyboard focus share one highlight: two different treatments for
     "the row you are about to choose" is a distinction without a difference. */
  optionActiveBackground: brand.colors.backgroundAlt,
  optionSelectedText: brand.colors.accentDark,
  optionCheck: brand.colors.accent,
  optionCount: brand.colors.textMuted,
  optionDivider: brand.colors.border,

  focus: brand.colors.accent,
};

const layout = {
  radius: 2,
  menuOffset: 6,
  menuMaxHeight: 288,
  checkColumn: 18,
};

const typography = {
  family: brand.typography.body,
  buttonSize: 14,
  optionSize: 13.5,
  countSize: 11.5,
};

const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
.kr-select { position: relative; }

.kr-select__label {
  display: block;
  margin-bottom: 8px;
  color: ${color.buttonPlaceholder};
  font-family: ${typography.family};
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.kr-select__button {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 0;
  background: transparent;
  border: 0;
  color: ${color.buttonText};
  font-family: ${typography.family};
  font-size: ${typography.buttonSize}px;
  text-align: left;
  cursor: pointer;
}
.kr-select__button:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 4px; }

.kr-select__icon {
  display: inline-flex;
  flex-shrink: 0;
  color: ${color.buttonIcon};
}
.kr-select__value {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kr-select__value--placeholder { color: ${color.buttonPlaceholder}; }

.kr-select__caret {
  display: inline-flex;
  flex-shrink: 0;
  color: ${color.buttonCaret};
  transition: transform ${180}ms ${ease};
}
.kr-select--open .kr-select__caret { transform: rotate(180deg); }

/* ── menu ─────────────────────────────────────────────── */
.kr-select__menu {
  position: absolute;
  top: calc(100% + ${layout.menuOffset}px);
  z-index: 60;
  min-width: 100%;
  max-height: ${layout.menuMaxHeight}px;
  margin: 0;
  padding: 6px;
  overflow-y: auto;
  overscroll-behavior: contain;
  list-style: none;
  background: ${color.menuBackground};
  border: 1px solid ${color.menuBorder};
  border-radius: ${layout.radius}px;
  box-shadow: ${color.menuShadow};
  animation: kr-select-in 160ms ${ease} both;
}
.kr-select__menu--start { left: 0; }
.kr-select__menu--end { right: 0; }

@keyframes kr-select-in {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: none; }
}

.kr-select__option {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 10px;
  border-radius: ${layout.radius}px;
  color: ${color.optionText};
  font-family: ${typography.family};
  font-size: ${typography.optionSize}px;
  line-height: 1.4;
  cursor: pointer;
  /* No transition: the highlight follows the cursor and the arrow keys, and a
     fade makes fast movement look like it is lagging behind. */
}
.kr-select__option--active { background: ${color.optionActiveBackground}; }
.kr-select__option--selected {
  color: ${color.optionSelectedText};
  font-weight: 600;
}
.kr-select__option--placeholder { color: ${color.optionPlaceholder}; }
.kr-select__option--placeholder.kr-select__option--selected {
  color: ${color.optionPlaceholder};
  font-weight: 400;
}

/* Reserved whether or not a tick is showing, so choosing one does not shunt
   every label sideways. */
.kr-select__option-check {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 ${layout.checkColumn}px;
  width: ${layout.checkColumn}px;
  color: ${color.optionCheck};
}
.kr-select__option-label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kr-select__option-count {
  flex-shrink: 0;
  color: ${color.optionCount};
  font-size: ${typography.countSize}px;
  font-variant-numeric: tabular-nums;
}

@media (prefers-reduced-motion: reduce) {
  .kr-select__menu { animation: none; }
  .kr-select__caret { transition: none; }
}
`;

const template: SelectTemplate = { css };

export default template;
