import React from "react";
import { LuSearchX } from "react-icons/lu";

import PropertyCard from "../property/PropertyCard";
import type { PropertyCardTemplate } from "../../templates/property-card/default-template";
import type { Property } from "../property/types";
import type { ViewMode } from "./types";

export type PropertyResultsProps = {
  properties: Property[];
  view: ViewMode;
  cardTemplate: PropertyCardTemplate;
  /** Total matching, which may exceed what is rendered. */
  total: number;
  canLoadMore: boolean;
  onLoadMore: () => void;
  onClearFilters: () => void;
  hasActiveFilters: boolean;
  /** Renders skeletons instead of results while the URL is being read. */
  loading?: boolean;
  pageSize?: number;
};

/** A card-shaped placeholder, so the layout does not jump when results land. */
function SkeletonCard({ view }: { view: ViewMode }) {
  return (
    <div
      className={`kr-skel${view === "list" ? " kr-skel--list" : ""}`}
      aria-hidden="true"
    >
      <div className="kr-skel__media" />
      <div className="kr-skel__body">
        <span className="kr-skel__line kr-skel__line--type" />
        <span className="kr-skel__line kr-skel__line--title" />
        <span className="kr-skel__line kr-skel__line--location" />
        <span className="kr-skel__line kr-skel__line--stats" />
        <span className="kr-skel__line kr-skel__line--price" />
      </div>
    </div>
  );
}

/**
 * The results themselves.
 *
 * Grid and list are the same PropertyCard with a different `layout` prop, so
 * a change to the card reaches Featured Properties, Similar Properties and
 * this page at once. The container swaps class, the card swaps prop, and
 * nothing else differs between the two views.
 */
export default function PropertyResults({
  properties,
  view,
  cardTemplate,
  total,
  canLoadMore,
  onLoadMore,
  onClearFilters,
  hasActiveFilters,
  loading = false,
  pageSize = 6,
}: PropertyResultsProps) {
  if (loading) {
    return (
      <div className={`kr-results kr-results--${view}`}>
        {Array.from({ length: pageSize }, (_, index) => (
          <SkeletonCard key={index} view={view} />
        ))}
      </div>
    );
  }

  if (!properties.length) {
    return (
      <div className="kr-empty">
        <span className="kr-empty__icon" aria-hidden="true">
          <LuSearchX size={34} strokeWidth={1.3} />
        </span>
        <h2 className="kr-empty__title">No matches found</h2>
        <p className="kr-empty__text">
          We could not find a property matching all of your current filters.
        </p>

        <ul className="kr-empty__hints">
          <li>Try widening the monthly rent range</li>
          <li>Remove the bedroom or bathroom constraint</li>
          <li>Search a nearby city instead</li>
        </ul>

        <div className="kr-empty__actions">
          {hasActiveFilters ? (
            <button
              type="button"
              className="kr-btn kr-btn--gold"
              onClick={onClearFilters}
            >
              Clear Filters
            </button>
          ) : null}
          <a className="kr-btn kr-btn--outline" href="/properties">
            View All Properties
          </a>
        </div>
      </div>
    );
  }

  return (
    <>
      <div className={`kr-results kr-results--${view}`}>
        {properties.map((property, index) => (
          <div className="kr-results__item" key={property.id}>
            <PropertyCard
              template={cardTemplate}
              property={property}
              layout={view}
              /* The first row is above the fold on most screens. */
              eager={index < 2}
            />
          </div>
        ))}
      </div>

      {canLoadMore ? (
        <div className="kr-more">
          <button type="button" className="kr-btn kr-btn--outline" onClick={onLoadMore}>
            Load More Properties
          </button>
          <p className="kr-more__status">
            Showing {properties.length} of {total} properties
          </p>
        </div>
      ) : null}
    </>
  );
}
