import React from "react";
import { LuX } from "react-icons/lu";

import type { ActiveChip } from "./types";

export type ActiveFilterChipsProps = {
  chips: ActiveChip[];
  onClearAll: () => void;
};

/**
 * The active filters, each removable on its own.
 *
 * This is what tells a visitor WHY they are looking at four properties
 * instead of twelve. Without it the only way back is to reopen every filter
 * group and hunt for what is ticked.
 */
export default function ActiveFilterChips({
  chips,
  onClearAll,
}: ActiveFilterChipsProps) {
  if (!chips.length) return null;

  return (
    <div className="kr-chips">
      <ul className="kr-chips__list">
        {chips.map((chip) => (
          <li key={chip.id} className="kr-chips__item">
            <button
              type="button"
              className="kr-chip"
              onClick={chip.clear}
              aria-label={`Remove filter: ${chip.label}`}
            >
              <span className="kr-chip__label">{chip.label}</span>
              <span className="kr-chip__x" aria-hidden="true">
                <LuX size={13} strokeWidth={2} />
              </span>
            </button>
          </li>
        ))}
      </ul>

      <button type="button" className="kr-chips__clear" onClick={onClearAll}>
        Clear All
      </button>
    </div>
  );
}
