import React from "react";
import { LuGrid2X2, LuList } from "react-icons/lu";

import SelectMenu from "../shared/SelectMenu";

import type { SortKey, ViewMode } from "./types";

export type SortOption = { value: SortKey; label: string };

export const SORT_OPTIONS: SortOption[] = [
  { value: "recommended", label: "Recommended" },
  { value: "rent-asc", label: "Rent: Low to High" },
  { value: "rent-desc", label: "Rent: High to Low" },
  { value: "newest", label: "Newest" },
  { value: "name-asc", label: "Name: A-Z" },
];

export type ResultsToolbarProps = {
  count: number;
  sort: SortKey;
  view: ViewMode;
  onSortChange: (next: SortKey) => void;
  onViewChange: (next: ViewMode) => void;
};

/**
 * Result count on the left, sort and view on the right.
 *
 * The count is announced politely so a screen reader hears the result of a
 * filter change without the focus being yanked out of the filter panel.
 */
export default function ResultsToolbar({
  count,
  sort,
  view,
  onSortChange,
  onViewChange,
}: ResultsToolbarProps) {
  return (
    <div className="kr-toolbar">
      <p className="kr-toolbar__count" role="status" aria-live="polite">
        <strong>{count}</strong>{" "}
        {/* Singular matters: "1 Properties Found" is the sort of detail that
            quietly tells a visitor nobody checked the page. */}
        {count === 1 ? "Property Found" : "Properties Found"}
      </p>

      <div className="kr-toolbar__controls">
        <div className="kr-sort">
          <span className="kr-sort__label" aria-hidden="true">
            Sort by
          </span>
          <div className="kr-sort__field">
            <SelectMenu
              label="Sort by"
              value={sort}
              /* Sorting always has a value, so there is nothing to clear to. */
              clearable={false}
              options={SORT_OPTIONS.map((option) => ({
                value: option.value,
                label: option.label,
              }))}
              onChange={(next) => onSortChange(next as SortKey)}
              align="end"
            />
          </div>
        </div>

        <div className="kr-view" role="group" aria-label="Results layout">
          <button
            type="button"
            className={`kr-view__btn${view === "grid" ? " kr-view__btn--on" : ""}`}
            aria-label="Grid view"
            aria-pressed={view === "grid"}
            onClick={() => onViewChange("grid")}
          >
            <LuGrid2X2 size={16} strokeWidth={1.75} />
          </button>
          <button
            type="button"
            className={`kr-view__btn${view === "list" ? " kr-view__btn--on" : ""}`}
            aria-label="List view"
            aria-pressed={view === "list"}
            onClick={() => onViewChange("list")}
          >
            <LuList size={16} strokeWidth={1.75} />
          </button>
        </div>
      </div>
    </div>
  );
}
