import React from "react";

import type { FacetOption } from "./types";

export type AmenityFilterProps = {
  options: FacetOption[];
  selected: string[];
  idPrefix: string;
  onChange: (next: string[]) => void;
};

/**
 * Amenity checkboxes.
 *
 * Selections combine with AND: a property must have every ticked amenity, not
 * just one of them. That is what people mean when they tick two things.
 */
export default function AmenityFilter({
  options,
  selected,
  idPrefix,
  onChange,
}: AmenityFilterProps) {
  return (
    <ul className="kr-filters__checks">
      {options.map((option) => {
        const id = `${idPrefix}-amenity-${option.value.toLowerCase().replace(/\s+/g, "-")}`;
        const checked = selected.includes(option.value);
        return (
          <li key={option.value}>
            <input
              id={id}
              type="checkbox"
              className="kr-filters__checkbox"
              checked={checked}
              disabled={!checked && option.count === 0}
              onChange={() =>
                onChange(
                  checked
                    ? selected.filter((current) => current !== option.value)
                    : [...selected, option.value]
                )
              }
            />
            <label className="kr-filters__check-label" htmlFor={id}>
              <span className="kr-filters__check-text">{option.label}</span>
              <span className="kr-filters__check-count">{option.count}</span>
            </label>
          </li>
        );
      })}
    </ul>
  );
}
