import React from "react";

import type { FacetOption } from "./types";

export type BedroomFilterProps = {
  options: FacetOption[];
  selected: number[];
  onChange: (next: number[]) => void;
};

/**
 * Bedroom counts as toggle buttons rather than a dropdown.
 *
 * Bedrooms is the filter people reach for first and change most, so it is
 * worth the extra width: one tap instead of open, scan, select, close.
 * Multiple counts can be active at once, which a single select cannot do.
 */
export default function BedroomFilter({
  options,
  selected,
  onChange,
}: BedroomFilterProps) {
  return (
    <div className="kr-pills" role="group" aria-label="Bedrooms">
      {options.map((option) => {
        const value = Number(option.value);
        const active = selected.includes(value);
        return (
          <button
            key={option.value}
            type="button"
            className={`kr-pill${active ? " kr-pill--on" : ""}`}
            aria-pressed={active}
            disabled={!active && option.count === 0}
            onClick={() =>
              onChange(
                active
                  ? selected.filter((current) => current !== value)
                  : [...selected, value]
              )
            }
          >
            {option.label}
            <span className="kr-pill__count">{option.count}</span>
          </button>
        );
      })}
    </div>
  );
}
