import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import type { Property } from "../property/types";
import type {
  ActiveChip,
  Facets,
  Filters,
  SearchState,
  SortKey,
  ViewMode,
} from "./types";

/** Bedroom buttons collapse at this count: 3 means "3 or more". */
export const BEDROOMS_PLUS_FROM = 3;

const SORT_KEYS: SortKey[] = [
  "recommended",
  "rent-asc",
  "rent-desc",
  "newest",
  "name-asc",
];

export const EMPTY_FILTERS: Filters = {
  location: "",
  types: [],
  bedrooms: [],
  bathrooms: null,
  rentMin: null,
  rentMax: null,
  amenities: [],
  availability: [],
};

const VIEW_STORAGE_KEY = "kr:properties:view";

const list = (value: string | null): string[] =>
  value
    ? value
        .split(",")
        .map((part) => part.trim())
        .filter(Boolean)
    : [];

const numberOrNull = (value: string | null): number | null => {
  if (value === null || value.trim() === "") return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};

/**
 * Reads filters out of a query string.
 *
 * Tolerant by design: the homepage search posts a plain GET here, and a
 * shared link may be old or hand-edited. Anything unrecognised is ignored
 * rather than throwing, so a bad parameter never costs the visitor the page.
 */
export function filtersFromQuery(search: string): { filters: Filters; sort: SortKey } {
  const params = new URLSearchParams(search);

  // `q` is what the homepage hero has always posted; `location` is the name
  // the shareable URL uses. Accept both so old links keep working.
  const location = (params.get("location") || params.get("q") || "").trim();

  const bedrooms = list(params.get("bedrooms"))
    .map((value) => (value.toLowerCase() === "studio" ? 0 : Number(value)))
    .filter((value) => Number.isFinite(value) && value >= 0);

  const sortParam = params.get("sort") as SortKey | null;

  return {
    filters: {
      location,
      types: list(params.get("type")),
      bedrooms,
      bathrooms: numberOrNull(params.get("bathrooms")),
      rentMin: numberOrNull(params.get("rentMin")),
      rentMax: numberOrNull(params.get("rentMax")),
      amenities: list(params.get("amenities")),
      availability: list(params.get("availability")),
    },
    sort: sortParam && SORT_KEYS.includes(sortParam) ? sortParam : "recommended",
  };
}

/** The inverse: only non-default values are written, so URLs stay short. */
export function queryFromFilters(filters: Filters, sort: SortKey): string {
  const params = new URLSearchParams();

  if (filters.location) params.set("location", filters.location);
  if (filters.types.length) params.set("type", filters.types.join(","));
  if (filters.bedrooms.length) {
    params.set(
      "bedrooms",
      filters.bedrooms
        .slice()
        .sort((a, b) => a - b)
        .join(",")
    );
  }
  if (filters.bathrooms !== null) params.set("bathrooms", String(filters.bathrooms));
  if (filters.rentMin !== null) params.set("rentMin", String(filters.rentMin));
  if (filters.rentMax !== null) params.set("rentMax", String(filters.rentMax));
  if (filters.amenities.length) params.set("amenities", filters.amenities.join(","));
  if (filters.availability.length) {
    params.set("availability", filters.availability.join(","));
  }
  if (sort !== "recommended") params.set("sort", sort);

  const query = params.toString();
  return query ? `?${query}` : "";
}

/* ── individual predicates ──────────────────────────────────
   Kept separate so facet counting can apply every filter EXCEPT the one it is
   counting, which is what stops a facet from zeroing out its own options. */

/**
 * The one text-search rule on this site.
 *
 * Exported because the CMS searches properties too, when a manager is choosing
 * which ones to suggest alongside another. Two implementations of "does this
 * property match what I typed" is two behaviours to explain, so there is one.
 *
 * Widened to the three fields it actually reads, so it works on a stored record
 * as well as a resolved one — the difference between them is the photograph,
 * which text search has no opinion about.
 */
export type SearchableProperty = Pick<Property, "title" | "location" | "type">;

export const matchesTerm = (property: SearchableProperty, term: string) => {
  if (!term.trim()) return true;
  const needle = term.trim().toLowerCase();
  return (
    property.title.toLowerCase().includes(needle) ||
    property.location.toLowerCase().includes(needle) ||
    property.type.toLowerCase().includes(needle)
  );
};

const matchesLocation = (property: Property, term: string) =>
  matchesTerm(property, term);

const matchesType = (property: Property, types: string[]) =>
  !types.length || types.includes(property.type);

const matchesBedrooms = (property: Property, bedrooms: number[]) =>
  !bedrooms.length ||
  bedrooms.some((value) =>
    value >= BEDROOMS_PLUS_FROM
      ? property.bedrooms >= value
      : property.bedrooms === value
  );

const matchesBathrooms = (property: Property, min: number | null) =>
  min === null || property.bathrooms >= min;

const matchesRent = (property: Property, min: number | null, max: number | null) =>
  (min === null || property.rent >= min) && (max === null || property.rent <= max);

/** Every selected amenity must be present, not just one of them. */
const matchesAmenities = (property: Property, amenities: string[]) =>
  !amenities.length ||
  amenities.every((amenity) => (property.amenities || []).includes(amenity));

const matchesAvailability = (property: Property, availability: string[]) =>
  !availability.length ||
  (property.availability ? availability.includes(property.availability) : false);

type FacetKey =
  | "location"
  | "types"
  | "bedrooms"
  | "bathrooms"
  | "rent"
  | "amenities"
  | "availability";

/** Applies every predicate except `skip`. */
function passes(property: Property, filters: Filters, skip?: FacetKey): boolean {
  if (skip !== "location" && !matchesLocation(property, filters.location)) return false;
  if (skip !== "types" && !matchesType(property, filters.types)) return false;
  if (skip !== "bedrooms" && !matchesBedrooms(property, filters.bedrooms)) return false;
  if (skip !== "bathrooms" && !matchesBathrooms(property, filters.bathrooms)) return false;
  if (skip !== "rent" && !matchesRent(property, filters.rentMin, filters.rentMax)) {
    return false;
  }
  if (skip !== "amenities" && !matchesAmenities(property, filters.amenities)) return false;
  if (skip !== "availability" && !matchesAvailability(property, filters.availability)) {
    return false;
  }
  return true;
}

const bedroomLabel = (value: number) => {
  if (value === 0) return "Studio";
  if (value >= BEDROOMS_PLUS_FROM) return `${value}+`;
  return String(value);
};

const bedroomChipLabel = (value: number) => {
  if (value === 0) return "Studio";
  if (value >= BEDROOMS_PLUS_FROM) return `${value}+ Bedrooms`;
  return value === 1 ? "1 Bedroom" : `${value} Bedrooms`;
};

function buildFacets(properties: Property[], filters: Filters): Facets {
  const countWith = (key: FacetKey, predicate: (p: Property) => boolean) =>
    properties.filter((p) => predicate(p) && passes(p, filters, key)).length;

  const uniqueTypes = Array.from(new Set(properties.map((p) => p.type))).sort();

  const bedroomValues = Array.from(
    new Set(
      properties.map((p) =>
        p.bedrooms >= BEDROOMS_PLUS_FROM ? BEDROOMS_PLUS_FROM : p.bedrooms
      )
    )
  ).sort((a, b) => a - b);

  const bathroomValues = Array.from(
    new Set(properties.map((p) => Math.floor(p.bathrooms)))
  )
    .filter((value) => value >= 1)
    .sort((a, b) => a - b);

  const uniqueAmenities = Array.from(
    new Set(properties.flatMap((p) => p.amenities || []))
  ).sort();

  const uniqueAvailability = Array.from(
    new Set(
      properties
        .map((p) => p.availability)
        .filter((value): value is string => Boolean(value))
    )
  ).sort();

  const rents = properties.map((p) => p.rent).filter((value) => Number.isFinite(value));

  return {
    types: uniqueTypes.map((type) => ({
      value: type,
      label: type,
      count: countWith("types", (p) => p.type === type),
    })),
    bedrooms: bedroomValues.map((value) => ({
      value: String(value),
      label: bedroomLabel(value),
      count: countWith("bedrooms", (p) =>
        value >= BEDROOMS_PLUS_FROM ? p.bedrooms >= value : p.bedrooms === value
      ),
    })),
    bathrooms: bathroomValues.map((value) => ({
      value: String(value),
      label: `${value}+`,
      count: countWith("bathrooms", (p) => p.bathrooms >= value),
    })),
    amenities: uniqueAmenities.map((amenity) => ({
      value: amenity,
      label: amenity,
      count: countWith("amenities", (p) => (p.amenities || []).includes(amenity)),
    })),
    availability: uniqueAvailability.map((value) => ({
      value,
      label: value,
      count: countWith("availability", (p) => p.availability === value),
    })),
    rentBounds: {
      min: rents.length ? Math.min(...rents) : 0,
      max: rents.length ? Math.max(...rents) : 0,
    },
  };
}

function sortResults(properties: Property[], sort: SortKey): Property[] {
  const sorted = properties.slice();
  const listed = (p: Property) => (p.listedOn ? Date.parse(p.listedOn) : 0);

  switch (sort) {
    case "rent-asc":
      return sorted.sort((a, b) => a.rent - b.rent);
    case "rent-desc":
      return sorted.sort((a, b) => b.rent - a.rent);
    case "newest":
      return sorted.sort((a, b) => listed(b) - listed(a));
    case "name-asc":
      return sorted.sort((a, b) => a.title.localeCompare(b.title));
    case "recommended":
    default:
      // Featured first, then most recently listed. Deliberately defined here
      // rather than relying on array order, which is data-entry order.
      return sorted.sort((a, b) => {
        const featured = Number(Boolean(b.featured)) - Number(Boolean(a.featured));
        return featured !== 0 ? featured : listed(b) - listed(a);
      });
  }
}

export type UseSearchStateOptions = {
  properties: Property[];
  /** How many results to reveal per page. */
  pageSize?: number;
};

/**
 * All search behaviour, in one place.
 *
 * The URL is the source of truth for anything shareable — filters and sort —
 * so browser back and forward work, a search can be bookmarked, and the
 * homepage search can link straight into a filtered result set. View mode is
 * excluded on purpose: it is a display preference, not part of the search.
 *
 * Server rendering has no URL to read, so the statically generated HTML holds
 * the full, unfiltered list — real cards a crawler and a visitor without
 * JavaScript can both read — and the URL filters apply on hydration. Reading
 * the URL during the first client render instead would produce different
 * markup from the server and break hydration, which costs more than one
 * frame of unfiltered results.
 */
export default function useSearchState({
  properties,
  pageSize = 6,
}: UseSearchStateOptions): SearchState {
  const [filters, setFiltersState] = useState<Filters>(EMPTY_FILTERS);
  const [sort, setSortState] = useState<SortKey>("recommended");
  const [view, setViewState] = useState<ViewMode>("grid");
  const [page, setPage] = useState(1);
  const [hydrating, setHydrating] = useState(true);

  /* Suppresses the URL write that would otherwise fire for the state we just
     read out of the URL. */
  const skipNextWrite = useRef(true);

  const applyFromLocation = useCallback(() => {
    const parsed = filtersFromQuery(window.location.search);
    skipNextWrite.current = true;
    setFiltersState(parsed.filters);
    setSortState(parsed.sort);
    setPage(1);
  }, []);

  useEffect(() => {
    applyFromLocation();
    setHydrating(false);

    try {
      const stored = window.sessionStorage.getItem(VIEW_STORAGE_KEY);
      if (stored === "grid" || stored === "list") setViewState(stored);
    } catch {
      // Private browsing can refuse sessionStorage entirely. The default
      // view is perfectly usable, so this is not worth surfacing.
    }

    // Back and forward should move through searches, not just page history.
    window.addEventListener("popstate", applyFromLocation);
    return () => window.removeEventListener("popstate", applyFromLocation);
  }, [applyFromLocation]);

  /* Filters and sort go into the URL. pushState so back returns to the
     previous search; the initial read is skipped so it does not duplicate the
     entry the visitor arrived on. */
  useEffect(() => {
    if (hydrating) return;
    if (skipNextWrite.current) {
      skipNextWrite.current = false;
      return;
    }
    const query = queryFromFilters(filters, sort);
    const next = `${window.location.pathname}${query}`;
    if (next !== `${window.location.pathname}${window.location.search}`) {
      window.history.pushState({}, "", next);
    }
  }, [filters, sort, hydrating]);

  const setFilters = useCallback((next: Partial<Filters>) => {
    setFiltersState((current) => ({ ...current, ...next }));
    setPage(1);
  }, []);

  const setSort = useCallback((next: SortKey) => {
    setSortState(next);
    setPage(1);
  }, []);

  const setView = useCallback((next: ViewMode) => {
    setViewState(next);
    try {
      window.sessionStorage.setItem(VIEW_STORAGE_KEY, next);
    } catch {
      // See above: a refused write costs nothing but the preference.
    }
  }, []);

  const clearAll = useCallback(() => {
    setFiltersState(EMPTY_FILTERS);
    setSortState("recommended");
    setPage(1);
  }, []);

  const results = useMemo(
    () => sortResults(properties.filter((p) => passes(p, filters)), sort),
    [properties, filters, sort]
  );

  const facets = useMemo(() => buildFacets(properties, filters), [properties, filters]);

  const chips = useMemo<ActiveChip[]>(() => {
    const out: ActiveChip[] = [];

    if (filters.location) {
      out.push({
        id: `location:${filters.location}`,
        label: filters.location,
        clear: () => setFilters({ location: "" }),
      });
    }
    filters.types.forEach((type) => {
      out.push({
        id: `type:${type}`,
        label: type,
        clear: () =>
          setFilters({ types: filters.types.filter((value) => value !== type) }),
      });
    });
    filters.bedrooms.forEach((value) => {
      out.push({
        id: `bedrooms:${value}`,
        label: bedroomChipLabel(value),
        clear: () =>
          setFilters({
            bedrooms: filters.bedrooms.filter((current) => current !== value),
          }),
      });
    });
    if (filters.bathrooms !== null) {
      out.push({
        id: `bathrooms:${filters.bathrooms}`,
        label: `${filters.bathrooms}+ Bathrooms`,
        clear: () => setFilters({ bathrooms: null }),
      });
    }
    if (filters.rentMin !== null || filters.rentMax !== null) {
      const min = filters.rentMin === null ? "Any" : `$${filters.rentMin}`;
      const max = filters.rentMax === null ? "Any" : `$${filters.rentMax}`;
      out.push({
        id: "rent",
        label: `${min} – ${max}`,
        clear: () => setFilters({ rentMin: null, rentMax: null }),
      });
    }
    filters.amenities.forEach((amenity) => {
      out.push({
        id: `amenity:${amenity}`,
        label: amenity,
        clear: () =>
          setFilters({
            amenities: filters.amenities.filter((value) => value !== amenity),
          }),
      });
    });
    filters.availability.forEach((value) => {
      out.push({
        id: `availability:${value}`,
        label: value,
        clear: () =>
          setFilters({
            availability: filters.availability.filter((current) => current !== value),
          }),
      });
    });

    return out;
  }, [filters, setFilters]);

  const visible = useMemo(() => results.slice(0, page * pageSize), [
    results,
    page,
    pageSize,
  ]);

  return {
    filters,
    sort,
    view,
    results,
    visible,
    facets,
    chips,
    hasActiveFilters: chips.length > 0,
    canLoadMore: visible.length < results.length,
    setFilters,
    setSort,
    setView,
    loadMore: () => setPage((current) => current + 1),
    clearAll,
    hydrating,
  };
}
