import React, { useEffect, useState } from "react";
import { LuHouse, LuMapPin, LuSearch } from "react-icons/lu";

import SelectMenu from "../shared/SelectMenu";

import { BEDROOMS_PLUS_FROM } from "./useSearchState";
import type { FacetOption, Filters } from "./types";

export type PropertySearchBarProps = {
  filters: Filters;
  typeOptions: FacetOption[];
  bedroomOptions: FacetOption[];
  setFilters: (next: Partial<Filters>) => void;
};

const bedroomText = (value: number) => {
  if (value === 0) return "Studio";
  if (value >= BEDROOMS_PLUS_FROM) return `${value}+ Bedrooms`;
  return value === 1 ? "1 Bedroom" : `${value} Bedrooms`;
};

/**
 * The search panel that overlaps the bottom of the mini hero.
 *
 * The same four-part shape as the homepage search in MTC-KRP-003 — type,
 * keyword, a control, and a gold submit — so arriving here from the homepage
 * feels like the same instrument rather than a second one.
 *
 * It carries no Filters button of its own. Every filter is already on screen
 * in the sidebar at desktop widths, and below that the sticky filter bar owns
 * that job — a third way in only duplicated the other two.
 *
 * It is a real form: submitting commits the keyword, and the type and bedroom
 * selects apply immediately, because a dropdown that needs a second click to
 * take effect is a dropdown people click twice and then distrust.
 */
export default function PropertySearchBar({
  filters,
  typeOptions,
  bedroomOptions,
  setFilters,
}: PropertySearchBarProps) {
  /* Local while typing so each keystroke does not re-filter and re-push the
     URL; committed on submit or blur. */
  const [term, setTerm] = useState(filters.location);

  useEffect(() => {
    setTerm(filters.location);
  }, [filters.location]);

  const singleType = filters.types.length === 1 ? filters.types[0] : "";
  const singleBedroom =
    filters.bedrooms.length === 1 ? String(filters.bedrooms[0]) : "";

  /* Only commit when the term actually changed. setFilters builds a new object
     every call, so committing an unchanged term still re-ran every downstream
     memo and re-rendered the page for nothing. */
  const commitTerm = () => {
    const next = term.trim();
    if (next !== filters.location) setFilters({ location: next });
  };

  return (
    <form
      className="kr-psearch"
      role="search"
      onSubmit={(event) => {
        event.preventDefault();
        commitTerm();
      }}
    >
      <div className="kr-psearch__field kr-psearch__field--select">
        <SelectMenu
          label="Property type"
          placeholder="Property Type"
          value={singleType}
          options={typeOptions.map((option) => ({
            value: option.value,
            label: option.label,
            count: option.count,
          }))}
          onChange={(next) => setFilters({ types: next ? [next] : [] })}
          icon={<LuHouse size={16} strokeWidth={1.6} />}
        />
      </div>

      <span className="kr-psearch__divider" aria-hidden="true" />

      <div className="kr-psearch__field kr-psearch__field--query">
        <span className="kr-psearch__icon" aria-hidden="true">
          <LuMapPin size={16} strokeWidth={1.6} />
        </span>
        <label className="kr-sr-only" htmlFor="kr-psearch-location">
          City, neighborhood or property name
        </label>
        <input
          id="kr-psearch-location"
          type="search"
          className="kr-psearch__input"
          placeholder="City, neighborhood or property name"
          autoComplete="off"
          value={term}
          onChange={(event) => setTerm(event.target.value)}
          onBlur={commitTerm}
        />
      </div>

      <span className="kr-psearch__divider" aria-hidden="true" />

      <div className="kr-psearch__field kr-psearch__field--select kr-psearch__field--beds">
        <SelectMenu
          label="Bedrooms"
          placeholder="Bedrooms"
          value={singleBedroom}
          options={bedroomOptions.map((option) => ({
            value: option.value,
            label: bedroomText(Number(option.value)),
            count: option.count,
          }))}
          onChange={(next) =>
            setFilters({ bedrooms: next ? [Number(next)] : [] })
          }
        />
      </div>

      <button type="submit" className="kr-btn kr-btn--gold kr-psearch__submit">
        <LuSearch size={15} strokeWidth={1.9} aria-hidden="true" />
        Search
      </button>
    </form>
  );
}
