import React from "react";
import { LuSearch } from "react-icons/lu";

import AmenityFilter from "./AmenityFilter";
import BedroomFilter from "./BedroomFilter";
import FilterGroup from "./FilterGroup";
import RentFilter from "./RentFilter";
import type { Facets, Filters } from "./types";

export type PropertyFiltersProps = {
  filters: Filters;
  facets: Facets;
  setFilters: (next: Partial<Filters>) => void;
  clearAll: () => void;
  hasActiveFilters: boolean;
  /** Hidden inside the mobile drawer, which carries its own title. */
  showHeading?: boolean;
  /** Disambiguates input ids when the panel is rendered twice. */
  idPrefix?: string;
};

const toggle = (values: string[], value: string) =>
  values.includes(value)
    ? values.filter((current) => current !== value)
    : [...values, value];

/**
 * The filter panel.
 *
 * One component for both the desktop sidebar and the mobile drawer — the
 * drawer supplies its own chrome and renders this inside it, so there is no
 * second set of filters to keep in step.
 *
 * Every option comes from `facets`, which is derived from the property data.
 * Nothing here is hard-coded, so a filter can never offer something no
 * property has.
 */
export default function PropertyFilters({
  filters,
  facets,
  setFilters,
  clearAll,
  hasActiveFilters,
  showHeading = true,
  idPrefix = "kr-filter",
}: PropertyFiltersProps) {
  return (
    <div className="kr-filters">
      {showHeading ? (
        <div className="kr-filters__head">
          <h2 className="kr-filters__title">Filter Properties</h2>
          <p className="kr-filters__lede">Narrow your search</p>
        </div>
      ) : null}

      <FilterGroup
        title="Location"
        defaultOpen
        activeCount={filters.location ? 1 : 0}
      >
        <div className="kr-filters__search">
          <span className="kr-filters__search-icon" aria-hidden="true">
            <LuSearch size={15} strokeWidth={1.6} />
          </span>
          <label className="kr-sr-only" htmlFor={`${idPrefix}-location`}>
            Search location
          </label>
          <input
            id={`${idPrefix}-location`}
            type="search"
            className="kr-filters__input"
            placeholder="Search location..."
            value={filters.location}
            onChange={(event) => setFilters({ location: event.target.value })}
          />
        </div>
      </FilterGroup>

      <FilterGroup
        title="Property Type"
        defaultOpen
        activeCount={filters.types.length}
      >
        <ul className="kr-filters__checks">
          {facets.types.map((option) => {
            const id = `${idPrefix}-type-${option.value.toLowerCase()}`;
            const checked = filters.types.includes(option.value);
            return (
              <li key={option.value}>
                <input
                  id={id}
                  type="checkbox"
                  className="kr-filters__checkbox"
                  checked={checked}
                  /* Zero results is worth showing rather than hiding: it tells
                     the visitor the option exists and why it is empty. */
                  disabled={!checked && option.count === 0}
                  onChange={() => setFilters({ types: toggle(filters.types, option.value) })}
                />
                <label className="kr-filters__check-label" htmlFor={id}>
                  <span className="kr-filters__check-text">{option.label}</span>
                  <span className="kr-filters__check-count">{option.count}</span>
                </label>
              </li>
            );
          })}
        </ul>
      </FilterGroup>

      <FilterGroup title="Bedrooms" defaultOpen activeCount={filters.bedrooms.length}>
        <BedroomFilter
          options={facets.bedrooms}
          selected={filters.bedrooms}
          onChange={(bedrooms) => setFilters({ bedrooms })}
        />
      </FilterGroup>

      <FilterGroup
        title="Bathrooms"
        activeCount={filters.bathrooms === null ? 0 : 1}
      >
        <div className="kr-pills" role="group" aria-label="Minimum bathrooms">
          {facets.bathrooms.map((option) => {
            const value = Number(option.value);
            const active = filters.bathrooms === value;
            return (
              <button
                key={option.value}
                type="button"
                className={`kr-pill${active ? " kr-pill--on" : ""}`}
                aria-pressed={active}
                disabled={!active && option.count === 0}
                onClick={() => setFilters({ bathrooms: active ? null : value })}
              >
                {option.label}
                <span className="kr-pill__count">{option.count}</span>
              </button>
            );
          })}
        </div>
      </FilterGroup>

      <FilterGroup
        title="Monthly Rent"
        activeCount={filters.rentMin !== null || filters.rentMax !== null ? 1 : 0}
      >
        <RentFilter
          bounds={facets.rentBounds}
          min={filters.rentMin}
          max={filters.rentMax}
          idPrefix={idPrefix}
          onChange={(rentMin, rentMax) => setFilters({ rentMin, rentMax })}
        />
      </FilterGroup>

      <FilterGroup title="Amenities" activeCount={filters.amenities.length}>
        <AmenityFilter
          options={facets.amenities}
          selected={filters.amenities}
          idPrefix={idPrefix}
          onChange={(amenities) => setFilters({ amenities })}
        />
      </FilterGroup>

      <FilterGroup title="Availability" activeCount={filters.availability.length}>
        <ul className="kr-filters__checks">
          {facets.availability.map((option) => {
            const id = `${idPrefix}-avail-${option.value.toLowerCase().replace(/\s+/g, "-")}`;
            const checked = filters.availability.includes(option.value);
            return (
              <li key={option.value}>
                <input
                  id={id}
                  type="checkbox"
                  className="kr-filters__checkbox"
                  checked={checked}
                  disabled={!checked && option.count === 0}
                  onChange={() =>
                    setFilters({
                      availability: toggle(filters.availability, option.value),
                    })
                  }
                />
                <label className="kr-filters__check-label" htmlFor={id}>
                  <span className="kr-filters__check-text">{option.label}</span>
                  <span className="kr-filters__check-count">{option.count}</span>
                </label>
              </li>
            );
          })}
        </ul>
      </FilterGroup>

      <div className="kr-filters__foot">
        <button
          type="button"
          className="kr-filters__clear"
          onClick={clearAll}
          disabled={!hasActiveFilters}
        >
          Clear All
        </button>
      </div>
    </div>
  );
}
