import React, { useEffect, useState } from "react";

export type RentFilterProps = {
  /** Lowest and highest rent in the data, used as the input placeholders. */
  bounds: { min: number; max: number };
  min: number | null;
  max: number | null;
  idPrefix: string;
  onChange: (min: number | null, max: number | null) => void;
};

const parse = (value: string): number | null => {
  const digits = value.replace(/[^\d]/g, "");
  if (!digits) return null;
  const parsed = Number(digits);
  return Number.isFinite(parsed) ? parsed : null;
};

/**
 * Minimum and maximum monthly rent.
 *
 * Two number inputs rather than a slider: a slider needs invented steps and
 * is awkward on a touch screen, and people looking at rent usually have a
 * figure in mind. The placeholders are the real bounds of the data, so no
 * price range is invented — they show what actually exists.
 *
 * Committed on blur or Enter rather than on every keystroke, so typing "1200"
 * does not filter through 1, 12 and 120 on the way.
 */
export default function RentFilter({
  bounds,
  min,
  max,
  idPrefix,
  onChange,
}: RentFilterProps) {
  const [minText, setMinText] = useState(min === null ? "" : String(min));
  const [maxText, setMaxText] = useState(max === null ? "" : String(max));

  // Keep the inputs honest when the filter is cleared from a chip or Clear All.
  useEffect(() => {
    setMinText(min === null ? "" : String(min));
  }, [min]);
  useEffect(() => {
    setMaxText(max === null ? "" : String(max));
  }, [max]);

  const commit = () => {
    const nextMin = parse(minText);
    const nextMax = parse(maxText);
    // A reversed range returns nothing and reads as a bug, so swap it.
    if (nextMin !== null && nextMax !== null && nextMin > nextMax) {
      onChange(nextMax, nextMin);
      return;
    }
    onChange(nextMin, nextMax);
  };

  const onKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Enter") {
      event.preventDefault();
      commit();
    }
  };

  return (
    <div className="kr-rent">
      <div className="kr-rent__field">
        <label className="kr-sr-only" htmlFor={`${idPrefix}-rent-min`}>
          Minimum monthly rent
        </label>
        <span className="kr-rent__prefix" aria-hidden="true">
          $
        </span>
        <input
          id={`${idPrefix}-rent-min`}
          className="kr-rent__input"
          type="text"
          inputMode="numeric"
          placeholder={String(bounds.min)}
          value={minText}
          onChange={(event) => setMinText(event.target.value)}
          onBlur={commit}
          onKeyDown={onKeyDown}
        />
      </div>

      <span className="kr-rent__to">to</span>

      <div className="kr-rent__field">
        <label className="kr-sr-only" htmlFor={`${idPrefix}-rent-max`}>
          Maximum monthly rent
        </label>
        <span className="kr-rent__prefix" aria-hidden="true">
          $
        </span>
        <input
          id={`${idPrefix}-rent-max`}
          className="kr-rent__input"
          type="text"
          inputMode="numeric"
          placeholder={String(bounds.max)}
          value={maxText}
          onChange={(event) => setMaxText(event.target.value)}
          onBlur={commit}
          onKeyDown={onKeyDown}
        />
      </div>
    </div>
  );
}
