import React, { useEffect, useRef } from "react";
import { LuX } from "react-icons/lu";

export type MobileFilterDrawerProps = {
  open: boolean;
  onClose: () => void;
  /** Live count, so the action button says what closing will show. */
  resultCount: number;
  onClearAll: () => void;
  hasActiveFilters: boolean;
  children: React.ReactNode;
};

const FOCUSABLE =
  'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

/**
 * The mobile filter drawer.
 *
 * Slides up over the results and stays open while several choices are made —
 * closing on every tap would make multi-filter searches miserable. The bottom
 * bar is sticky and its label tracks the live count, so the visitor can see
 * the effect of each choice before committing to it.
 *
 * Focus is trapped while open and returned to the trigger on close, and
 * Escape closes it, because a full-screen overlay you cannot tab out of is
 * a trap in the literal sense.
 */
export default function MobileFilterDrawer({
  open,
  onClose,
  resultCount,
  onClearAll,
  hasActiveFilters,
  children,
}: MobileFilterDrawerProps) {
  const panelRef = useRef<HTMLDivElement | null>(null);
  const restoreTo = useRef<HTMLElement | null>(null);

  /* Read through a ref rather than depending on the prop.
     The callers pass an inline arrow, so `onClose` is a new function on every
     render. As an effect dependency that re-ran the whole setup on each render:
     the cleanup moved focus back to the trigger, the next run moved it into the
     panel, and any handler listening for blur — the search input commits its
     term there — set state and started the cycle again. That is an infinite
     render loop, which is what froze the page. */
  const onCloseRef = useRef(onClose);
  useEffect(() => {
    onCloseRef.current = onClose;
  });

  useEffect(() => {
    if (!open) return;

    restoreTo.current = document.activeElement as HTMLElement | null;

    // The page behind must not scroll under the drawer.
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    const panel = panelRef.current;
    const first = panel?.querySelector<HTMLElement>(FOCUSABLE);
    first?.focus();

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        onCloseRef.current();
        return;
      }
      if (event.key !== "Tab" || !panel) return;

      const focusable = Array.from(panel.querySelectorAll<HTMLElement>(FOCUSABLE)).filter(
        (element) => element.offsetParent !== null
      );
      if (!focusable.length) return;

      const firstEl = focusable[0];
      const lastEl = focusable[focusable.length - 1];

      if (event.shiftKey && document.activeElement === firstEl) {
        event.preventDefault();
        lastEl.focus();
      } else if (!event.shiftKey && document.activeElement === lastEl) {
        event.preventDefault();
        firstEl.focus();
      }
    };

    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.body.style.overflow = previousOverflow;
      restoreTo.current?.focus();
    };
  }, [open]);

  if (!open) return null;

  return (
    <div className="kr-drawer" role="presentation">
      <div className="kr-drawer__veil" onClick={onClose} aria-hidden="true" />

      <div
        className="kr-drawer__panel"
        role="dialog"
        aria-modal="true"
        aria-label="Filter properties"
        ref={panelRef}
      >
        <div className="kr-drawer__head">
          <h2 className="kr-drawer__title">Filter Properties</h2>
          <button
            type="button"
            className="kr-drawer__close"
            onClick={onClose}
            aria-label="Close filters"
          >
            <LuX size={18} strokeWidth={1.75} />
          </button>
        </div>

        <div className="kr-drawer__body">{children}</div>

        <div className="kr-drawer__foot">
          <button
            type="button"
            className="kr-drawer__clear"
            onClick={onClearAll}
            disabled={!hasActiveFilters}
          >
            Clear All
          </button>
          <button type="button" className="kr-btn kr-btn--gold" onClick={onClose}>
            {resultCount === 1 ? "Show 1 Property" : `Show ${resultCount} Properties`}
          </button>
        </div>
      </div>
    </div>
  );
}
