import React, { useState } from "react";
import { LuSlidersHorizontal } from "react-icons/lu";

import cardTemplate from "../../config/property-card--template";
import searchTemplate from "../../config/properties-search--template";
import selectTemplate from "../../config/select--template";
import ActiveFilterChips from "../../modules/properties-search/ActiveFilterChips";
import MobileFilterDrawer from "../../modules/properties-search/MobileFilterDrawer";
import PropertiesMiniHero from "../../modules/properties-search/PropertiesMiniHero";
import PropertyFilters from "../../modules/properties-search/PropertyFilters";
import PropertyResults from "../../modules/properties-search/PropertyResults";
import PropertySearchBar from "../../modules/properties-search/PropertySearchBar";
import ResultsToolbar from "../../modules/properties-search/ResultsToolbar";
import useSearchState from "../../modules/properties-search/useSearchState";
import { publishedOnly } from "../../modules/property/derive";
import { catalogue as records } from "../property/catalogue";
import { resolveProperties } from "../property/property-images";
import searchEnabled from "../../toggles/properties-search";

import hero from "../../../images/search/search-hero-1.jpg";
import heroSm from "../../../images/search/search-hero-1-sm.jpg";

/** How many results a page reveals before Load More. */
const PAGE_SIZE = 6;

/**
 * The properties search page, configured.
 *
 * Content and data live here; structure, style and colour come from the
 * template; behaviour comes from useSearchState. The property list is the
 * same `properties` array the homepage and every property page already read,
 * so there is no second dataset to drift out of sync.
 */
export default function PropertiesSearchX() {
  /* Drafts are not searchable. A listing nobody has finished is not a
     listing, whatever its availability says. */
  const all = React.useMemo(() => resolveProperties(publishedOnly(records)), []);
  const search = useSearchState({ properties: all, pageSize: PAGE_SIZE });
  const [drawerOpen, setDrawerOpen] = useState(false);

  if (!searchEnabled) return null;

  const filterPanel = (
    <PropertyFilters
      filters={search.filters}
      facets={search.facets}
      setFilters={search.setFilters}
      clearAll={search.clearAll}
      hasActiveFilters={search.hasActiveFilters}
    />
  );

  return (
    <>
      <style>{searchTemplate.css}</style>
      {/* The card styles travel with whatever renders the card. The
          carousels emit these too; on this page nothing else would. */}
      <style>{cardTemplate.css}</style>
      {/* The listbox that replaces the native selects in the search bar and
          the sort control. */}
      <style>{selectTemplate.css}</style>

      <PropertiesMiniHero
        image={{
          src: hero,
          srcSet: `${heroSm} 1200w, ${hero} 1920w`,
          alt: heroAlt,
        }}
        eyebrow="Find Your Next Home"
        title="Explore Available Properties"
        lede={
          "Search Kelley Road properties by location, home type and the " +
          "features that matter to you."
        }
        backgroundText="Properties"
      />

      <div className="kr-psearch-wrap">
        <PropertySearchBar
          filters={search.filters}
          typeOptions={search.facets.types}
          bedroomOptions={search.facets.bedrooms}
          setFilters={search.setFilters}
        />
      </div>

      <section className={searchTemplate.rootClass}>
        <div className="kr-psearch-page__inner">
          <aside className="kr-psearch-page__aside" aria-label="Filter properties">
            {filterPanel}
          </aside>

          <div className="kr-psearch-page__main">
            {/* Replaces the sidebar below 1024px. */}
            <div className="kr-fbar">
              <button
                type="button"
                className="kr-fbar__btn"
                onClick={() => setDrawerOpen(true)}
              >
                <LuSlidersHorizontal size={15} strokeWidth={1.6} aria-hidden="true" />
                Filters
                {search.chips.length ? (
                  <span className="kr-fbar__count">{search.chips.length}</span>
                ) : null}
              </button>
            </div>

            <ActiveFilterChips chips={search.chips} onClearAll={search.clearAll} />

            <ResultsToolbar
              count={search.results.length}
              sort={search.sort}
              view={search.view}
              onSortChange={search.setSort}
              onViewChange={search.setView}
            />

            <PropertyResults
              properties={search.visible}
              view={search.view}
              cardTemplate={cardTemplate}
              total={search.results.length}
              canLoadMore={search.canLoadMore}
              onLoadMore={search.loadMore}
              onClearFilters={search.clearAll}
              hasActiveFilters={search.hasActiveFilters}
              /* The property data is local, so results are never actually
                 pending. PropertyResults keeps its skeleton state for the day
                 this reads from an API — showing one now would be a loading
                 state for something that is already loaded. */
              loading={false}
              pageSize={PAGE_SIZE}
            />
          </div>
        </div>
      </section>

      <MobileFilterDrawer
        open={drawerOpen}
        onClose={() => setDrawerOpen(false)}
        resultCount={search.results.length}
        onClearAll={search.clearAll}
        hasActiveFilters={search.hasActiveFilters}
      >
        <PropertyFilters
          filters={search.filters}
          facets={search.facets}
          setFilters={search.setFilters}
          clearAll={search.clearAll}
          hasActiveFilters={search.hasActiveFilters}
          showHeading={false}
          idPrefix="kr-drawer-filter"
        />
      </MobileFilterDrawer>
    </>
  );
}

/** TODO(client): replace with a Kelley Road community photograph. */
const heroAlt =
  "A long row of modern low-rise apartment buildings in cream stone and " +
  "timber cladding, with glass-railed balconies and large windows, seen " +
  "across landscaped park grounds of mown lawn, pine and birch trees, " +
  "shrubs turning red and gold, and a curving paved footpath, with a " +
  "playground and swing set at the left.";
