import React, { useEffect, useId, useMemo, useRef, useState } from "react";
import { LuCheck, LuChevronDown } from "react-icons/lu";

export type SelectOption = {
  value: string;
  label: string;
  /** Facet count, shown muted on the right. */
  count?: number;
};

export type SelectMenuProps = {
  /** Accessible name. Rendered visually only if `showLabel` is set. */
  label: string;
  showLabel?: boolean;
  value: string;
  options: SelectOption[];
  /** Shown when nothing is chosen; also the label of the clear-to-empty row. */
  placeholder?: string;
  /** Whether the placeholder is selectable, clearing the choice. */
  clearable?: boolean;
  onChange: (value: string) => void;
  /** Leading icon inside the button. */
  icon?: React.ReactNode;
  /** Extra class on the root, for width and variant styling. */
  className?: string;
  /** Which edge the menu lines up with when it is wider than the button. */
  align?: "start" | "end";
};

/**
 * A listbox that can actually be designed.
 *
 * A native select renders its option list in the operating system, not the
 * page: the blue highlight, the system font and the row height are all outside
 * CSS's reach, so a styled control opened onto an unstyled list. This is the
 * standard combobox pattern instead — a button plus a listbox — so the open
 * state belongs to the same design as the closed one.
 *
 * The keyboard contract matches the native control it replaces: Up and Down
 * move, Home and End jump, Enter and Space choose, Escape closes without
 * choosing, and typing letters jumps to a matching option. Nothing here is a
 * div pretending to be a control; the roles and aria-activedescendant are what
 * a screen reader reads.
 */
export default function SelectMenu({
  label,
  showLabel = false,
  value,
  options,
  placeholder = "Select",
  clearable = true,
  onChange,
  icon,
  className,
  align = "start",
}: SelectMenuProps) {
  const reactId = useId();
  const buttonId = `${reactId}-button`;
  const listId = `${reactId}-list`;

  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(0);

  const rootRef = useRef<HTMLDivElement | null>(null);
  const buttonRef = useRef<HTMLButtonElement | null>(null);
  const listRef = useRef<HTMLUListElement | null>(null);
  const typeahead = useRef({ text: "", at: 0 });

  /* The placeholder is a real row when it clears the choice, so the visitor
     can undo a selection with the same gesture that made it. */
  const rows = useMemo<SelectOption[]>(
    () => (clearable ? [{ value: "", label: placeholder }, ...options] : options),
    [clearable, options, placeholder]
  );

  const selectedIndex = rows.findIndex((row) => row.value === value);
  const selected = selectedIndex >= 0 ? rows[selectedIndex] : undefined;

  const openMenu = (startAt?: number) => {
    setActiveIndex(startAt ?? (selectedIndex >= 0 ? selectedIndex : 0));
    setOpen(true);
  };

  const closeMenu = (returnFocus = true) => {
    setOpen(false);
    if (returnFocus) buttonRef.current?.focus();
  };

  const choose = (index: number) => {
    const row = rows[index];
    if (!row) return;
    onChange(row.value);
    closeMenu();
  };

  /* Pointer down rather than click: a click on another control would other-
     wise land while this menu still covers it. */
  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open]);

  /* A menu anchored to a control has to follow it, and it cannot follow a
     control that has scrolled away underneath it. */
  useEffect(() => {
    if (!open) return;
    const close = () => setOpen(false);
    window.addEventListener("resize", close);
    return () => window.removeEventListener("resize", close);
  }, [open]);

  /* Keep the active row in view when the list is long enough to scroll. */
  useEffect(() => {
    if (!open) return;
    const list = listRef.current;
    const row = list?.children[activeIndex] as HTMLElement | undefined;
    row?.scrollIntoView({ block: "nearest" });
  }, [open, activeIndex]);

  const move = (delta: number) => {
    setActiveIndex((current) => {
      const next = current + delta;
      if (next < 0) return rows.length - 1;
      if (next >= rows.length) return 0;
      return next;
    });
  };

  const onKeyDown = (event: React.KeyboardEvent) => {
    if (!open) {
      if (["ArrowDown", "ArrowUp", "Enter", " "].includes(event.key)) {
        event.preventDefault();
        openMenu();
      }
      return;
    }

    switch (event.key) {
      case "Escape":
        event.preventDefault();
        closeMenu();
        return;
      case "Tab":
        // Tab commits nothing and moves on, as a native select does.
        setOpen(false);
        return;
      case "ArrowDown":
        event.preventDefault();
        move(1);
        return;
      case "ArrowUp":
        event.preventDefault();
        move(-1);
        return;
      case "Home":
        event.preventDefault();
        setActiveIndex(0);
        return;
      case "End":
        event.preventDefault();
        setActiveIndex(rows.length - 1);
        return;
      case "Enter":
      case " ":
        event.preventDefault();
        choose(activeIndex);
        return;
      default:
        break;
    }

    // Typeahead: consecutive letters accumulate, a pause starts a new search.
    if (event.key.length === 1 && !event.metaKey && !event.ctrlKey && !event.altKey) {
      const now = event.timeStamp;
      const state = typeahead.current;
      state.text = now - state.at > 800 ? event.key : state.text + event.key;
      state.at = now;

      const needle = state.text.toLowerCase();
      const found = rows.findIndex((row) => row.label.toLowerCase().startsWith(needle));
      if (found >= 0) setActiveIndex(found);
    }
  };

  const rootClass = ["kr-select", open ? "kr-select--open" : "", className]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={rootClass} ref={rootRef}>
      <label
        className={showLabel ? "kr-select__label" : "kr-sr-only"}
        htmlFor={buttonId}
      >
        {label}
      </label>

      <button
        type="button"
        id={buttonId}
        ref={buttonRef}
        className="kr-select__button"
        role="combobox"
        aria-controls={listId}
        aria-expanded={open}
        aria-haspopup="listbox"
        aria-activedescendant={open ? `${listId}-${activeIndex}` : undefined}
        onClick={() => (open ? closeMenu(false) : openMenu())}
        onKeyDown={onKeyDown}
      >
        {icon ? (
          <span className="kr-select__icon" aria-hidden="true">
            {icon}
          </span>
        ) : null}
        <span
          className={`kr-select__value${
            selected && selected.value ? "" : " kr-select__value--placeholder"
          }`}
        >
          {selected ? selected.label : placeholder}
        </span>
        <span className="kr-select__caret" aria-hidden="true">
          <LuChevronDown size={15} strokeWidth={1.75} />
        </span>
      </button>

      {open ? (
        <ul
          className={`kr-select__menu kr-select__menu--${align}`}
          id={listId}
          role="listbox"
          aria-label={label}
          ref={listRef}
          tabIndex={-1}
        >
          {rows.map((row, index) => {
            const isSelected = row.value === value;
            const isActive = index === activeIndex;
            return (
              <li
                key={row.value || "__placeholder"}
                id={`${listId}-${index}`}
                role="option"
                aria-selected={isSelected}
                className={[
                  "kr-select__option",
                  isActive ? "kr-select__option--active" : "",
                  isSelected ? "kr-select__option--selected" : "",
                  row.value ? "" : "kr-select__option--placeholder",
                ]
                  .filter(Boolean)
                  .join(" ")}
                /* Pointer, not click: mousedown on the list must not blur the
                   button before the choice is registered. */
                onPointerDown={(event) => {
                  event.preventDefault();
                  choose(index);
                }}
                onMouseEnter={() => setActiveIndex(index)}
              >
                <span className="kr-select__option-check" aria-hidden="true">
                  {isSelected ? <LuCheck size={14} strokeWidth={2} /> : null}
                </span>
                <span className="kr-select__option-label">{row.label}</span>
                {typeof row.count === "number" ? (
                  <span className="kr-select__option-count">{row.count}</span>
                ) : null}
              </li>
            );
          })}
        </ul>
      ) : null}
    </div>
  );
}
